      this.pos++;
      const inner = this.parseSum(site);
      const close = this.peek();
      if (!isPunct(close, ')')) throw errorAt(t, 'Nawias ( nie ma pary ).');
      this.pos++;
      this.parenDepth--;
      return inner;
    }
    throw errorAt(t, `Oczekiwano wartości, a znaleziono „${t.text}”.`);
  }

  private nameValue(t: Token, site: Site, consumedBefore: number): Expr {
    // `consumedBefore` is 1 when a legacy `:` was read first; the name itself is one token.
    this.pos += 1;
