    this.zoomBy(factor, event.offsetX, event.offsetY);
  }

  private key(event: KeyboardEvent): void {
    const step = 40;
    switch (event.key) {
      case 'ArrowLeft':
        this.panPixels(step, 0);
        break;
      case 'ArrowRight':
        this.panPixels(-step, 0);
        break;
      case 'ArrowUp':
        this.panPixels(0, step);
        break;
      case 'ArrowDown':
        this.panPixels(0, -step);
        break;
      case '+':
      case '=':
        this.zoomBy(1.25);
        break;
      case '-':
      case '_':
        this.zoomBy(0.8);
        break;
      case 'Home':
        this.fitToScene();
        break;
      default:
        return;
    }
    event.preventDefault();
  }
}

