cat > src/ui/toast.ts <<'EOF'
import { h } from './dom';

export interface ToastAction {
  label: string;
  run: () => void;
}

/** Short messages at the bottom of the screen. An optional action (e.g. undo) can be attached. */
export function showToast(message: string, action?: ToastAction): void {
  const host = document.getElementById('toasts');
  if (!host) return;
  const toast = h(
    'div',
    { class: 'toast' },
    h('span', {}, message),
    action
      ? h('button', {
          type: 'button',
          class: 'btn small',
          on: {
            click: () => {
              action.run();
              toast.remove();
            },
          },
        }, action.label)
      : null,
  );
  host.append(toast);
  window.setTimeout(() => toast.remove(), action ? 12000 : 5000);
}
