cat > /tmp/pwprobe/probe2.mjs <<'EOF'
import { chromium } from 'playwright';
const base = process.env.BASE || 'http://127.0.0.1:8123/';
const browser = await chromium.launch();
const errors = [];
const newPage = async (opts = {}) => {
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 1, ...opts });
  page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) errors.push(`[${m.type()}] ${m.text()}`); });
  page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
  return page;
};
const wait = (page, ms) => page.waitForTimeout(ms);
const status = (page) => page.locator('#status-line').innerText();

// 1. Run the starter program, check status and screenshot.
let page = await newPage();
await page.goto(base + '#/', { waitUntil: 'load' });
await page.waitForFunction(() => window.logomocja);
await page.getByRole('button', { name: 'Uruchom' }).click();
await wait(page, 1200);
console.log('A status after run:', await status(page));
await page.screenshot({ path: '/tmp/shots/02-run.png' });
await page.getByRole('button', { name: 'Wznów' }).waitFor({ timeout: 2000 }).catch(() => {});

// 2. Set speed to instant via keyboard on the slider, then run an example through the dialog.
await page.getByRole('button', { name: 'Przykłady' }).click();
await wait(page, 300);
await page.screenshot({ path: '/tmp/shots/03-examples.png' });
await page.getByRole('button', { name: /Helisa/ }).click();
await wait(page, 1500);
console.log('B after helisa, status:', await status(page));
await page.screenshot({ path: '/tmp/shots/04-helisa-3d.png' });

// 3. Error marker: type an invalid line.
await page.locator('textarea.code-input').click();
await page.keyboard.press('Control+End');
await page.keyboard.type('\nnp 10 -5');
await wait(page, 500);
console.log('C status with error:', await status(page));
await page.screenshot({ path: '/tmp/shots/05-error.png' });

// 4. Reference page.
await page.goto(base + '#/pomoc', { waitUntil: 'load' });
await wait(page, 400);
await page.screenshot({ path: '/tmp/shots/06-pomoc.png' });
await page.goto(base + '#/?tryb=2d&kod=' + Buffer.from('powtorz 6 [np 60 pw 60]', 'utf8').toString('base64url'), { waitUntil: 'load' });
await wait(page, 1200);
console.log('D permalink status:', await status(page));
await page.screenshot({ path: '/tmp/shots/07-permalink.png' });
await page.close();

// 5. Phone layout.
page = await newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
await page.goto(base + '#/', { waitUntil: 'load' });
await page.waitForFunction(() => window.logomocja);
await wait(page, 300);
await page.screenshot({ path: '/tmp/shots/08-phone-code.png' });
await page.getByRole('button', { name: 'Rysunek' }).click();
await page.getByRole('button', { name: 'Uruchom' }).click();
await wait(page, 1500);
await page.screenshot({ path: '/tmp/shots/09-phone-view.png' });
await page.close();

// 6. Dark theme.
page = await newPage({ colorScheme: 'dark' });
await page.goto(base + '#/', { waitUntil: 'load' });
await page.waitForFunction(() => window.logomocja);
await page.getByRole('button', { name: 'Uruchom' }).click();
await wait(page, 1500);
await page.screenshot({ path: '/tmp/shots/10-dark.png' });
await page.close();

console.log('errors:', errors.length ? errors.join('\n') : 'none');
await browser.close();
EOF
